import { expect, test } from "@playwright/test";
import { loadBoard, openReproduction, startAt } from "./support.ts";

test("a repeated reveal is free, a mismatch ignores activations, and pairs match", async ({ page }) => {
  await page.clock.install();
  await startAt(page);
  const cards = page.locator(".memory-card");
  await cards.nth(0).click();
  await cards.nth(0).click();
  await expect(page.getByText("Moves: 0")).toBeVisible();
  await cards.nth(1).click();
  await expect(page.getByText("Moves: 1")).toBeVisible();
  await expect(page.getByText("No match. Cards close after a short pause.", { exact: true })).toBeVisible();
  await cards.nth(2).click();
  await expect(page.getByText("Moves: 1")).toBeVisible();
  await page.clock.runFor(799);
  await expect(cards.nth(0)).toHaveAttribute("aria-pressed", "true");
  await page.clock.runFor(1);
  await expect(cards.nth(0)).toHaveAccessibleName("Row 1, column 1, closed");
  await cards.nth(2).click();
  await cards.nth(6).click();
  await expect(page.getByText("Moves: 2")).toBeVisible();
  await expect(page.getByText("Pairs: 1/8")).toBeVisible();
  await expect(cards.nth(2)).toHaveAttribute("aria-disabled", "true");
});

test("each identical miss is announced once; focus and turn closure add no announcement", async ({ page }) => {
  await page.clock.install();
  await startAt(page);
  const live = page.locator('[aria-live="polite"]');
  await live.evaluate((region) => {
    region.setAttribute("data-announcements", "0");
    const observer = new MutationObserver((entries) => {
      const additions = entries.reduce((total, entry) => total + entry.addedNodes.length, 0);
      const count = Number(region.getAttribute("data-announcements")) + additions;
      region.setAttribute("data-announcements", String(count));
    });
    observer.observe(region, { childList: true, subtree: true });
  });
  const cards = page.locator(".memory-card");
  await cards.nth(0).click();
  await cards.nth(1).click();
  await expect(live).toHaveText("No match. Cards close after a short pause.");
  await expect(live).toHaveAttribute("data-announcements", "1");
  await page.clock.runFor(800);
  await expect(live).toHaveAttribute("data-announcements", "1");
  await cards.nth(2).focus();
  await page.keyboard.press("ArrowRight");
  await expect(cards.nth(3)).toBeFocused();
  await expect(live).toHaveAttribute("data-announcements", "1");
  await cards.nth(2).click();
  await cards.nth(3).click();
  await expect(live).toHaveText("No match. Cards close after a short pause.");
  await expect(live).toHaveAttribute("data-announcements", "2");
});

test("bad reproduction drafts keep the game; successful loads keep focus", async ({ page }) => {
  await startAt(page);
  const cards = page.locator(".memory-card");
  await cards.nth(0).click();
  await openReproduction(page);
  const boardCode = page.getByLabel("Board code");
  await boardCode.fill("np1-6-1");
  await cards.nth(1).click();
  await expect(boardCode).toHaveValue("np1-6-1");
  await boardCode.fill("np1-4-01");
  await page.getByRole("button", { name: "Load board" }).click();
  await expect(page.locator(".visible-status")).toHaveText("Invalid board code.");
  await expect(boardCode).toHaveValue("np1-4-01");
  await expect(cards.nth(0)).toHaveAccessibleName(/revealed/);
  const snapshot = page.getByLabel("Snapshot JSON");
  await snapshot.fill("{");
  await page.getByRole("button", { name: "Load snapshot" }).click();
  await expect(page.locator(".visible-status")).toHaveText("Invalid snapshot.");
  await expect(snapshot).toHaveValue("{");
  await expect(cards.nth(0)).toHaveAccessibleName(/revealed/);
  await loadBoard(page, "np1-6-1");
  await expect(page.getByRole("button", { name: "Load board" })).toBeFocused();
  await expect(page.getByLabel("Grid size")).toHaveValue("6");
});
import { expect, test } from "@playwright/test";
import { BOARD_SIZES, loadBoard, loadSnapshot, positionsForFaces, snapshot } from "./support.ts";

test("supported sizes, valid loads, and saves persist without touching unrelated keys", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByLabel("Grid size")).toHaveValue("4");
  await page.evaluate(() => localStorage.setItem("other.application.key", "preserve"));
  await page.getByLabel("Grid size").selectOption("6");
  await page.reload();
  await expect(page.getByLabel("Grid size")).toHaveValue("6");
  await loadBoard(page, "np1-8-1");
  await page.reload();
  await expect(page.getByLabel("Grid size")).toHaveValue("8");
  await expect.poll(() => page.evaluate(() => localStorage.getItem("other.application.key"))).toBe("preserve");
  await expect(page.evaluate(() => JSON.parse(localStorage.getItem("neon-pairs.preferences.v1") ?? "{}").size)).resolves.toBe(8);
  await loadBoard(page, "invalid");
  await page.reload();
  await expect(page.getByLabel("Grid size")).toHaveValue("8");
});

test("malformed and unavailable local storage leave play available", async ({ page }) => {
  await page.addInitScript(() => localStorage.setItem("neon-pairs.preferences.v1", '{"size":5}'));
  await page.goto("/");
  await expect(page.getByLabel("Grid size")).toHaveValue("4");
  await page.getByRole("button", { name: "Row 1, column 1, closed" }).click();
  await expect(page.getByRole("button", { name: /Row 1, column 1, .* revealed/ })).toBeVisible();
  await page.addInitScript(() => {
    Object.defineProperty(window, "localStorage", { configurable: true, get: () => { throw new Error("storage blocked"); } });
  });
  await page.reload();
  await expect(page.getByLabel("Grid size")).toHaveValue("4");
  await page.getByRole("button", { name: "Row 1, column 1, closed" }).click();
  await expect(page.getByRole("button", { name: /Row 1, column 1, .* revealed/ })).toBeVisible();
});

test("completed snapshot stays static without writing its moves to the best", async ({ page }) => {
  await page.addInitScript(() => localStorage.setItem("neon-pairs.best.v1", '{"4":3}'));
  await page.goto("/");
  await loadSnapshot(page, snapshot("np1-4-1", []));
  await expect(page.getByText("Best: 3")).toBeVisible();
  await expect(page.getByRole("button", { name: "Resume" })).toHaveCount(0);
  await expect(page.locator(".win-banner")).toHaveClass(/win-banner-static/);
  await expect.poll(() => page.evaluate(() => JSON.parse(localStorage.getItem("neon-pairs.best.v1") ?? "{}")["4"])).toBe(3);
});

test("better results replace best scores while equal and worse results preserve them", async ({ page }) => {
  const code = "np1-4-1";
  await page.clock.install();
  await page.goto("/");
  const finishOpenPairs = async (moves: number): Promise<void> => {
    const state = { ...snapshot(code, [0, 1]), moves };
    await loadSnapshot(page, state);
    await page.getByRole("button", { name: "Resume" }).click();
    for (const index of positionsForFaces(code, [0, 1])) await page.locator(".memory-card").nth(index).click();
  };
  await finishOpenPairs(9);
  await expect(page.getByText("Best: 11")).toBeVisible();
  await finishOpenPairs(6);
  await expect(page.getByText("Best: 8")).toBeVisible();
  await finishOpenPairs(6);
  await expect(page.getByText("Best: 8")).toBeVisible();
  await finishOpenPairs(7);
  await expect(page.getByText("Best: 8")).toBeVisible();
  await page.reload();
  await expect(page.getByText("Best: 8")).toBeVisible();
});

test("winning an imported unfinished game records its best for each supported board size", async ({ page }) => {
  await page.clock.install();
  await page.goto("/");
  for (const size of BOARD_SIZES) {
    const code = `np1-${size}-1`;
    await loadSnapshot(page, snapshot(code, [0]));
    await expect(page.getByLabel("Grid size")).toHaveValue(String(size));
    await page.getByRole("button", { name: "Resume" }).click();
    const pair = positionsForFaces(code, [0]);
    for (const index of pair) await page.locator(".memory-card").nth(index).click();
    const pairs = size * size / 2;
    await expect(page.getByText(`Pairs: ${pairs}/${pairs}`)).toBeVisible();
    await expect(page.getByText(`Best: ${pairs}`)).toBeVisible();
  }
});

