 1	import { forwardRef, useImperativeHandle, useRef, useState, type CSSProperties, type KeyboardEvent as ReactKeyboardEvent } from "react";
 2	import type { GameState } from "../state.ts";
 3	import { Card } from "./Card.tsx";
 4	import "./board.css";
 5	
 6	export interface BoardHandle {
 7	  focusRememberedCard(): void;
 8	}
 9	
10	type BoardStyle = CSSProperties & { readonly "--board-size": number };
11	
12	interface BoardProps {
13	  readonly game: GameState;
14	  readonly paused: boolean;
15	  readonly onActivate: (index: number) => void;
16	}
17	
18	export const Board = forwardRef<BoardHandle, BoardProps>(function Board({ game, paused, onActivate }, ref) {
19	  const [tabStop, setTabStop] = useState(0);
20	  const remembered = useRef(0);
21	  const buttons = useRef<Array<HTMLButtonElement | null>>([]);
22	  const scrollArea = useRef<HTMLDivElement>(null);
23	
24	  useImperativeHandle(ref, () => ({
25	    focusRememberedCard() { buttons.current[remembered.current]?.focus(); },
26	  }), []);
27	
28	  function focusCard(index: number): void {
29	    remembered.current = index;
30	    setTabStop(index);
31	    buttons.current[index]?.focus();
32	    scrollFocusedCard(index);
33	  }
34	
35	  function scrollFocusedCard(index: number): void {
36	    const card = buttons.current[index];
37	    const area = scrollArea.current;
38	    if (card === null || card === undefined || area === null) return;
39	    const cardBox = card.getBoundingClientRect();
40	    const areaBox = area.getBoundingClientRect();
41	    let left = area.scrollLeft;
42	    let top = area.scrollTop;
43	    if (cardBox.left < areaBox.left + 11) left -= areaBox.left + 11 - cardBox.left;
44	    else if (cardBox.right > areaBox.right - 11) left += cardBox.right - areaBox.right + 11;
