}

export function CardBack() {
  return (
    <svg aria-hidden="true" focusable="false" viewBox="0 0 100 100" className="card-back-mark">
      <polygon points="50,34 66,50 50,66 34,50" fill="none" stroke="#757C9A" strokeWidth="4" />
