    storage: storageRef.current,
    stateRef,
    pausedRef,
    lastClockRef,
    fractionRef,
    scores,
    setScores,
    setGame,
    setPaused,
    setRevision,
    setCelebrationId,
    setAnnouncement,
    setStatusMessage,
    syncClock,
  });

