export function initialState(board: BoardDescription): GameState {
  return {
    boardCode: board.code,
    size: board.size,
    deck: board.deck,
    matched: [],
    selection: { kind: "closed" },
    moves: 0,
    elapsedMs: 0,
    started: false,
